package pt.nossomenu;

import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import static pt.nossomenu.Model.*;

@Component
public class Catalogue implements CommandLineRunner {
    final Store db;final Products products;
    Catalogue(Store db,Products products){this.db=db;this.products=products;}
    @Override @Transactional public void run(String...args){
        if(!db.query(Recipe.class,"where x.familyId is null").isEmpty())return;
        add("Strogonoff de frango","Frango","Brasileira",10,15,false,"Corte o frango em tiras. Refogue a cebola no azeite, junte o frango e cozinhe até estar completamente cozinhado. Adicione os cogumelos, o tomate e as natas; deixe apurar 5 minutos. Sirva com arroz.","Frango|Carnes|500|g;Cebola|Legumes e verduras|1|un;Cogumelos|Legumes e verduras|200|g;Natas|Laticínios|200|ml;Polpa de tomate|Mercearia|100|ml;Azeite|Mercearia|15|ml");
        add("Puré de batata","Acompanhamentos","Portuguesa",10,25,true,"Descasque e corte as batatas. Coza em água durante 20 a 25 minutos até ficarem macias. Escorra, esmague e envolva o leite quente e a manteiga. Tempere a gosto.","Batata|Legumes e verduras|800|g;Leite|Laticínios|150|ml;Manteiga|Laticínios|30|g");
        add("Carne picada com legumes","Carnes","Brasileira",5,15,false,"Pique a cebola e a cenoura. Refogue no azeite. Junte a carne, desfaça-a com uma colher e cozinhe completamente. Adicione o tomate e deixe apurar. Sirva com arroz.","Carne picada|Carnes|500|g;Cebola|Legumes e verduras|1|un;Cenoura|Legumes e verduras|2|un;Polpa de tomate|Mercearia|200|ml;Azeite|Mercearia|15|ml");
        add("Batata frita no forno","Acompanhamentos","Portuguesa",10,35,true,"Aqueça o forno a 210 °C. Corte as batatas em palitos, seque e envolva no azeite. Espalhe num tabuleiro e asse 30 a 35 minutos, virando a meio.","Batata|Legumes e verduras|800|g;Azeite|Mercearia|30|ml");
        add("Coxas de frango assadas","Frango","Portuguesa",10,50,false,"Aqueça o forno a 200 °C. Tempere o frango com alho, limão, azeite e sal. Asse com as batatas cerca de 50 minutos, até o frango estar completamente cozinhado (75 °C no centro).", "Coxas de frango|Carnes|800|g;Batata|Legumes e verduras|600|g;Alho|Legumes e verduras|3|un;Limão|Frutas|1|un;Azeite|Mercearia|30|ml");
        add("Massa com molho branco","Massas","Brasileira",5,15,false,"Coza a massa conforme a embalagem. Derreta a manteiga, junte a farinha e mexa. Adicione o leite aos poucos, mexendo até engrossar. Junte o queijo e envolva a massa.","Massa|Mercearia|300|g;Leite|Laticínios|400|ml;Farinha|Mercearia|30|g;Manteiga|Laticínios|30|g;Queijo ralado|Laticínios|50|g");
        add("Massa com pesto e tomate","Massas","Portuguesa",5,12,false,"Coza a massa conforme a embalagem. Reserve uma chávena de água da cozedura. Misture a massa com o pesto, o tomate cortado e um pouco da água. Termine com queijo.","Massa|Mercearia|300|g;Pesto|Mercearia|80|g;Tomate|Legumes e verduras|200|g;Queijo ralado|Laticínios|40|g");
        add("Arroz branco soltinho","Arroz e feijão","Brasileira",5,18,true,"Refogue o alho no azeite. Junte o arroz e mexa. Adicione o dobro do volume de água quente, tempere e coza tapado em lume baixo cerca de 18 minutos.","Arroz|Mercearia|250|g;Alho|Legumes e verduras|1|un;Azeite|Mercearia|15|ml");
        add("Feijão rápido refogado","Arroz e feijão","Brasileira",5,10,true,"Use feijão já cozido. Refogue a cebola e o alho no azeite. Junte o feijão com um pouco do caldo e deixe apurar 10 minutos. Ajuste os temperos.","Feijão cozido|Mercearia|500|g;Cebola|Legumes e verduras|1|un;Alho|Legumes e verduras|2|un;Azeite|Mercearia|15|ml");
        add("Legumes salteados","Legumes","Portuguesa",8,10,true,"Corte os legumes em pedaços pequenos. Aqueça o azeite numa frigideira, junte a cenoura e os brócolos. Após 4 minutos junte a curgete e salteie até ficarem tenros.","Cenoura|Legumes e verduras|200|g;Brócolos|Legumes e verduras|250|g;Curgete|Legumes e verduras|200|g;Azeite|Mercearia|20|ml");
        add("Lasanha de carne","Massas","Brasileira",20,45,false,"Refogue a cebola e cozinhe completamente a carne. Junte o tomate e deixe apurar 10 minutos. Monte camadas de molho, massa e béchamel. Termine com queijo. Asse a 180 °C por 35 a 40 minutos ou conforme a massa.","Carne picada|Carnes|500|g;Cebola|Legumes e verduras|1|un;Polpa de tomate|Mercearia|400|ml;Massa para lasanha|Mercearia|250|g;Béchamel|Mercearia|500|ml;Queijo ralado|Laticínios|150|g");
        add("Massa à bolonhesa","Massas","Portuguesa",10,25,false,"Refogue a cebola e a cenoura. Junte a carne e cozinhe completamente. Adicione o tomate e deixe apurar 20 minutos. Coza a massa em paralelo e envolva no molho.","Carne picada|Carnes|400|g;Cebola|Legumes e verduras|1|un;Cenoura|Legumes e verduras|1|un;Polpa de tomate|Mercearia|400|ml;Massa|Mercearia|300|g;Azeite|Mercearia|15|ml");
        add("Omelete de espinafres","Refeições rápidas","Portuguesa",5,10,false,"Bata os ovos com o leite. Salteie os espinafres no azeite. Verta os ovos, adicione o queijo e cozinhe em lume baixo até o ovo ficar firme. Dobre e sirva.","Ovos|Mercearia|6|un;Espinafres|Legumes e verduras|150|g;Leite|Laticínios|50|ml;Queijo ralado|Laticínios|40|g;Azeite|Mercearia|15|ml");
        add("Arroz de atum e ervilhas","Peixe","Portuguesa",5,15,false,"Refogue a cebola. Junte o arroz, o dobro do volume em água e as ervilhas. Coza 15 minutos ou conforme o arroz. Envolva o atum escorrido e deixe repousar.","Arroz|Mercearia|250|g;Atum em conserva|Mercearia|240|g;Ervilhas|Congelados|150|g;Cebola|Legumes e verduras|1|un;Azeite|Mercearia|15|ml");
        add("Bacalhau à Brás","Peixe","Portuguesa",10,15,false,"Use bacalhau já demolhado e desfiado. Refogue a cebola e o alho. Junte o bacalhau e cozinhe 8 minutos. Adicione a batata palha e os ovos batidos, mexendo até os ovos estarem cozinhados.","Bacalhau demolhado|Peixe|400|g;Cebola|Legumes e verduras|2|un;Alho|Legumes e verduras|2|un;Ovos|Mercearia|4|un;Batata palha|Mercearia|200|g;Azeite|Mercearia|30|ml");
        add("Frango salteado com brócolos","Frango","Brasileira",8,12,false,"Corte o frango em tiras finas. Cozinhe no azeite até estar completamente cozinhado. Junte os brócolos em pedaços pequenos e um pouco de água; tape durante 5 minutos. Envolva o molho de soja.","Frango|Carnes|500|g;Brócolos|Legumes e verduras|400|g;Molho de soja|Mercearia|30|ml;Azeite|Mercearia|15|ml");
        add("Sopa de legumes e feijão","Sopas","Portuguesa",10,25,false,"Corte os legumes. Cubra com água e coza 25 minutos. Triture uma parte, junte o feijão já cozido e aqueça mais 3 minutos. Termine com o azeite.","Cenoura|Legumes e verduras|300|g;Batata|Legumes e verduras|300|g;Curgete|Legumes e verduras|250|g;Feijão cozido|Mercearia|300|g;Azeite|Mercearia|20|ml");
        add("Salada de grão com atum","Refeições rápidas","Portuguesa",10,0,false,"Escorra o grão e o atum. Corte o tomate e a cebola. Envolva tudo numa taça e tempere com azeite e sumo de limão. Sirva de imediato.","Grão cozido|Mercearia|500|g;Atum em conserva|Mercearia|240|g;Tomate|Legumes e verduras|200|g;Cebola|Legumes e verduras|1|un;Limão|Frutas|1|un;Azeite|Mercearia|20|ml");
    }
    void add(String name,String category,String cuisine,int prep,int cook,boolean side,String instructions,String data){
        Recipe recipe=new Recipe();recipe.name=name;recipe.description=side?"Um acompanhamento para completar a mesa.":"Uma receita simples para o dia a dia, em família.";recipe.category=category;recipe.cuisine=cuisine;recipe.prepMinutes=prep;recipe.cookMinutes=cook;recipe.servings=new BigDecimal("4");recipe.sideDish=side;recipe.instructions=instructions;
        for(String entry:data.split(";")){String[] fields=entry.split("\\|");Ingredient i=new Ingredient();i.name=fields[0];i.category=fields[1];i.quantity=new BigDecimal(fields[2]);i.unit=fields[3];i.productId=products.resolve(null,i.name,i.category,i.unit).id;recipe.ingredients.add(i);}db.save(recipe);
    }
}
